// Scatter bloom. A scatter plot that blooms onto a tilted plane while the camera drifts along it: thirteen hundred
// small points arrive over three seconds -- most on schedule, one in fourteen long before its turn, anywhere along
// the axis -- while the plane rolls a little, pushes in about a tenth (and overshoots on the way) and tracks two
// hundred pixels left. Nothing cuts and nothing lands; the only event in it is data.
//
// The plane is a flat sheet (header, hairline grid, week labels, a table) turned by the engine's own 3D layer
// transform under one perspective camera: the right edge is the near edge, so the near points are larger and, being
// out of focus, soft. The pose was fitted to the reference's week labels and table cells (rotateY about -12 degrees,
// roll about -6, perspective 554 reference px). The depth of field is made from bands of points blurred by their
// distance along the plane.
//
// Principles: slow in/slow out (the camera decays into its rest, no keyframe stops), follow through (the push
// overshoots by 2% and settles), staging (the data is the only event; the sheet is a still ground), timing (the cloud
// arrives on the reference's measured S-curve), secondary action (each point pops with a small overshoot).

import React from 'react';
import { z } from 'zod';
import { random } from 'remotion';
import { Camera, Ellipse, Layer, Path, Rect, Text, blur } from '@kinetographdev/core';
import { clamp01, hex, lerp, useFonts } from './lib.js';

export const SCATTER_FPS = 60;

export const scatterSchema = z.object({
  eyebrow: z.string().describe('Small line over the title.'),
  title: z.string().describe('The chart title.'),
  subtitle: z.string().describe('Small line under the title.'),
  weeks: z.array(z.string()).length(5).describe('The five x labels, left to right.'),
  columns: z.array(z.string()).length(4).describe('Table header cells.'),
  rows: z.array(z.array(z.string()).length(4)).max(3).describe('Table rows.'),
  points: z.number().int().min(100).max(3000).describe('How many points bloom onto the plane (reference 1300).'),
  seed: z.number().int().describe('Seed of the cloud.'),
  early: z.number().min(0).max(0.5).describe('Share of the points that arrive long before their turn (reference 1 in 14).'),
  accent: hex.describe('One end of the colour ramp of the points.'),
  accentB: hex.describe('The other end.'),
  ground: hex.describe('Background.'),
  bloomSeconds: z.number().min(1).max(12).describe('Seconds the points take to arrive (reference 3.1 s of the 3.27 s shot).'),
  holdSeconds: z.number().min(0).max(8).describe('Extra seconds to hold the last frame.'),
});
export type ScatterProps = z.infer<typeof scatterSchema>;

export const scatterDefaults: ScatterProps = {
  eyebrow: 'Dashboard · Render performance',
  title: 'Time to first frame',
  subtitle: 'Seconds per scene, by week',
  weeks: ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5'],
  columns: ['Scenes rendered', '+26%', 'p95', 'p99'],
  rows: [['23', '28', '1.9s', '4.1s'], ['34', '31', '2.4s', '6.0s']],
  points: 1300,
  seed: 7,
  early: 1 / 14,
  accent: '#4a62e0',
  accentB: '#b43ea2',
  ground: '#faf9f5',
  bloomSeconds: 3.1,
  holdSeconds: 0,
};

const END = 196;
export const scatterDuration = (p: ScatterProps) => END + Math.round(p.holdSeconds * SCATTER_FPS);

// ---------------------------------------------------------------------------------------------------------------
// Pose, fitted to the reference (reference px; the canvas is twice that).
const POSE = { rx: 0.67, ry: -12.03, rz0: -5.64, rz1: -6.3, persp: 554, tx0: 8.43, tx1: -95.85, ty0: 190.34, ty1: 192.25, sc0: 0.897 };
const COL = 170; // distance between columns on the plane
const ROW = 43; // distance between table rows

// How much of the cloud has arrived, by reference frame (measured off the area of colour).
const ARRIVED: [number, number][] = [[0, 0], [1, 0.024], [11, 0.035], [21, 0.052], [31, 0.073], [41, 0.115], [51, 0.146], [61, 0.187], [71, 0.243], [81, 0.325], [91, 0.406], [101, 0.52], [111, 0.621], [121, 0.729], [131, 0.793], [141, 0.857], [151, 0.893], [161, 0.948], [171, 0.979], [181, 0.998], [191, 1]];
const when = (q: number) => {
  for (let i = 1; i < ARRIVED.length; i++) if (q <= ARRIVED[i][1]) return lerp(ARRIVED[i - 1][0], ARRIVED[i][0], (q - ARRIVED[i - 1][1]) / (ARRIVED[i][1] - ARRIVED[i - 1][1]));
  return 191;
};

interface Dot { x: number; y: number; r: number; t: number; a: number; b: number }
const cache = new Map<string, Dot[]>();
function cloud(p: ScatterProps): Dot[] {
  const key = `${p.points}|${p.seed}|${p.early}|${p.bloomSeconds}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const k = (p.bloomSeconds * SCATTER_FPS) / 186; // stretch the reference's schedule
  const out: Dot[] = [];
  for (let i = 0; i < p.points; i++) {
    const R = (n: string) => random(`${p.seed}-${i}-${n}`);
    const v = Math.pow(R('x'), 0.72);
    const x = -405 + 925 * v;
    const hmax = Math.min(170, 22 + (x + 400) * 0.26);
    const y = -140 + 12 * (R('f') - 0.5) * (0.4 + (x + 400) / 900) - hmax * Math.pow(R('y'), 1.5);
    const r = 1.05 * (1.4 + 3.6 * Math.pow(R('r'), 2.2)) * (1 + 0.5 * clamp01((x - 100) / 400));
    const q = R('e') < p.early ? R('q') * v : clamp01(0.4 * v + 0.6 * R('j'));
    const b = (when(q) - 6) * k;
    out.push({ x, y, r, t: R('c'), a: 0.62 + 0.38 * R('a'), b });
  }
  cache.set(key, out);
  return out;
}

const rgb = (c: string) => [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];
const mix = (a: string, b: string, t: number) => {
  const x = rgb(a), y = rgb(b);
  return `rgb(${Math.round(lerp(x[0], y[0], t))},${Math.round(lerp(x[1], y[1], t))},${Math.round(lerp(x[2], y[2], t))})`;
};
const popScale = (a: number) => {
  if (a >= 1) return 1;
  const c1 = 1.9, c3 = c1 + 1;
  return 1 + c3 * Math.pow(a - 1, 3) + c1 * Math.pow(a - 1, 2);
};

const BANDS = 12;
const X_MIN = -405, X_MAX = 520;
const bandBlur = (xc: number) => 5 * clamp01((xc - 230) / 300); // reference px, in plane units

export const ScatterBloom: React.FC<{ f: number } & ScatterProps> = ({ f, ...p }) => {
  const fonts = useFonts();
  const g = Math.min(f, END);
  const pn = (1 - Math.exp(-g / 80)) / (1 - Math.exp(-END / 80));
  const over = 0.02 * Math.sin(Math.PI * Math.pow(pn, 0.7));
  const sc = lerp(POSE.sc0, 1, pn) + over;
  const rz = lerp(POSE.rz0, POSE.rz1, pn);
  const tx = lerp(POSE.tx0, POSE.tx1, pn);
  const ty = lerp(POSE.ty0, POSE.ty1, pn);

  const dots = cloud(p);
  const bands: React.ReactNode[][] = Array.from({ length: BANDS }, () => []);
  dots.forEach((d, i) => {
    const a = clamp01((g - d.b) / 12);
    if (a <= 0) return;
    const bi = Math.min(BANDS - 1, Math.max(0, Math.floor(((d.x - X_MIN) / (X_MAX - X_MIN)) * BANDS)));
    const r = d.r * popScale(a);
    bands[bi].push(
      <Ellipse key={i} id={`d${i}`} x={d.x - r} y={d.y - r} width={2 * r} height={2 * r}
        fill={mix(p.accent, p.accentB, d.t)} opacity={Math.min(1, a * 2) * d.a} />,
    );
  });

  const colX = (k: number) => (k - 2) * COL;
  const rowY = (j: number) => (j - 1.5) * ROW;
  const text = (id: string, s: string, x: number, y: number, size: number, color: string, weight = 400, w = 160) => (
    <Text key={id} id={id} x={x - w / 2} y={y - size * 0.62} font={fonts.sans} weight={weight} size={size} color={color} maxWidth={w} align="center">{s}</Text>
  );
  const lineColor = '#f2f1ec';

  return (
    <Layer id="root">
      <Camera perspective={POSE.persp * 2} />
      <Rect id="ground" width={1920} height={1080} fill={p.ground} />
      <Layer id="plane" x={960 + 2 * tx} y={540 + 2 * ty} scale={2 * sc} rotation={rz} rotateX={POSE.rx} rotateY={POSE.ry}>
        {/* header */}
        <Text id="eyebrow" x={-345} y={-433} font={fonts.sans} weight={400} size={9} color="#b4b2aa">{p.eyebrow}</Text>
        <Text id="title" x={-347} y={-402} font={fonts.sans} weight={400} size={19} color="#3f3d37">{p.title}</Text>
        <Text id="subtitle" x={-345} y={-369} font={fonts.sans} weight={400} size={8.5} color="#bdbbb3">{p.subtitle}</Text>

        {/* chart: a baseline and faint grid */}
        {[-145, -225, -305, -385].map((y, i) => (
          <Path key={i} id={`grid${i}`} d={`M-430 ${y}H600`} stroke={{ color: i === 0 ? '#ebeae4' : lineColor, width: 1 }} />
        ))}
        {Array.from({ length: BANDS }, (_, bi) => {
          const xc = X_MIN + ((bi + 0.5) / BANDS) * (X_MAX - X_MIN);
          const r = bandBlur(xc);
          return (
            <Layer key={bi} id={`band${bi}`} effects={r >= 0.5 ? [blur(r * 2)] : []}>
              {bands[bi]}
            </Layer>
          );
        })}

        {/* week labels */}
        {p.weeks.map((w, k) => (
          <Layer key={k} id={`wk${k}`} effects={k === 4 ? [blur(3)] : []}>
            {text(`wkt${k}`, w, colX(k), rowY(0), 12.5, '#a8a69e', 400)}
          </Layer>
        ))}

        {/* table */}
        <Rect id="bar" x={-421} y={rowY(1) - 18.5} width={985} height={37} radius={5}
          fill={{ type: 'linear', x0: -421, y0: 0, x1: 564, y1: 0, stops: [{ offset: 0, color: '#ecebe6' }, { offset: 0.5, color: '#dfded9' }, { offset: 1, color: '#f4f3ef' }] }} />
        {p.columns.map((c, k) => text(`h${k}`, c, colX(k), rowY(1), k === 0 ? 7.5 : 8.5, '#55534c', 500))}
        {p.rows.map((row, j) => row.map((c, k) => text(`r${j}-${k}`, c, colX(k), rowY(2 + j), 12.5, '#59574f', 400)))}
      </Layer>
    </Layer>
  );
};

// Shared parts of the chart components: themes, fonts, timing, number formatting, a camera, and the pieces every
// chart draws (a tooltip card, a hairline grid). Nothing here keeps state; every value is a function of the frame.

import React from 'react';
import { z } from 'zod';
import { Easing, interpolate } from 'remotion';
import { Layer, Path as Path_, Rect, Text, dropShadow } from '@kinetographdev/core';
import { loadFont as loadGeist } from '@remotion/google-fonts/Geist';
import { loadFont as loadGeistMono } from '@remotion/google-fonts/GeistMono';

export const W = 1920;
export const H = 1080;

// ---------------------------------------------------------------------------------------------------------------
// Timing

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
/** Slow in, slow out: the default for anything that travels. */
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
/** Fast start, long settle: for things that arrive. */
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);
export const linear = (t: number) => t;

/** 0..1 progress of frame f between frames a and b, eased and held outside. */
export const seg = (f: number, a: number, b: number, e: (t: number) => number = ease) =>
  interpolate(f, [a, b], [0, 1], { ...clamp, easing: e });
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
export const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

/** A monotone cubic through [frame, value] keys: a camera that glides through its marks without stopping or
 *  overshooting them. Flat at both ends (so it eases in and out of a hold). */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 1;
  while (f > k[i][0]) i++;
  const [x0, y0] = k[i - 1];
  const [x1, y1] = k[i];
  const h = x1 - x0;
  const t = (f - x0) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * h * d[i - 1] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * h * d[i];
}

// ---------------------------------------------------------------------------------------------------------------
// Colour

export const hexA = (hex: string, a: number) => {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.replace(/./g, '$&$&') : h.slice(0, 6), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${clamp01(a).toFixed(4)})`;
};

export interface Theme {
  bg: string;
  /** The card the chart sits on. */
  card: string;
  /** Primary type. */
  ink: string;
  /** Secondary type, axis labels. */
  muted: string;
  /** Hairlines, grid. */
  grid: string;
  /** Card border. */
  border: string;
  /** Fill of a tooltip. */
  tip: string;
  tipInk: string;
  shadow: string;
}

// Restrained, slightly warm neutrals; the accent carries all the colour.
export const THEMES: Record<'light' | 'dark', Theme> = {
  light: {
    bg: '#f3f3f1', card: '#fcfcfb', ink: '#14151a', muted: '#7b7d86', grid: '#d3d3cd', border: '#e6e6e2',
    tip: '#ffffff', tipInk: '#14151a', shadow: '#14151a1f',
  },
  dark: {
    bg: '#0b0c0f', card: '#121317', ink: '#f2f2f4', muted: '#7d808a', grid: '#363a43', border: '#23252b',
    tip: '#1a1c22', tipInk: '#f2f2f4', shadow: '#00000099',
  },
};

// A restrained set to pick from (oklch ~0.68 / 0.15, spread round the wheel), as hex.
export const PALETTE = ['#4f7cf6', '#e0855a', '#3fb58c', '#b476e0', '#d9b44a', '#e0607a'];

/** A stroke with the fields SCENE.md has (cap, join, dashArray) that the TypeScript `Stroke` type does not list yet;
 *  the element passes them through to the scene. */
export const stroke = (color: string, width: number, o: { cap?: 'butt' | 'round' | 'square'; join?: 'miter' | 'round' | 'bevel'; dash?: number[]; offset?: number } = {}) =>
  ({ color, width, ...(o.cap ? { cap: o.cap } : {}), ...(o.join ? { join: o.join } : {}), ...(o.dash ? { dashArray: o.dash } : {}), ...(o.offset ? { dashOffset: o.offset } : {}) }) as { color: string; width: number };

export const hex = z.string().regex(/^#[0-9a-fA-F]{6}$/).describe('A colour, #rrggbb.');
export const modeSchema = z.enum(['light', 'dark']).describe('Colour theme: light or dark.');

// ---------------------------------------------------------------------------------------------------------------
// Fonts

export interface Fonts {
  sans: string;
  mono: string;
}
export function useFonts(): Fonts {
  const sans = loadGeist('normal', { weights: ['400', '500', '600'] }).fontFamily;
  const mono = loadGeistMono('normal', { weights: ['400', '500', '600'] }).fontFamily;
  return { sans, mono };
}
/** Advance width of Geist Mono is 0.6 em, so a number's width is known without measuring. */
export const monoWidth = (text: string, size: number) => text.length * size * 0.6;

// ---------------------------------------------------------------------------------------------------------------
// Numbers

export interface NumFmt {
  prefix: string;
  suffix: string;
  decimals: number;
  /** Thousands separator, '' for none. */
  group: string;
}
export const fmtSchema = z
  .object({
    prefix: z.string().describe('Before the number, e.g. "$".'),
    suffix: z.string().describe('After the number, e.g. "%" or "k".'),
    decimals: z.number().int().min(0).max(4).describe('Digits after the decimal point.'),
    group: z.string().max(1).describe('Thousands separator, a comma by default. Empty for none.'),
  })
  .describe('How a number is written.');

export function fmt(v: number, f: NumFmt): string {
  const neg = v < 0;
  const fixed = Math.abs(v).toFixed(f.decimals);
  const [int, dec] = fixed.split('.');
  const grouped = f.group ? int.replace(/\B(?=(\d{3})+(?!\d))/g, f.group) : int;
  return `${neg ? '-' : ''}${f.prefix}${grouped}${dec ? '.' + dec : ''}${f.suffix}`;
}

// ---------------------------------------------------------------------------------------------------------------
// Camera

/** A camera on a world of pixel coordinates: the point (x, y) of the world lands in the middle of the frame, seen
 *  `zoom` times larger and, if asked, tilted. Give it an id; the motion blur matches sub-frames by id. */
export const Cam: React.FC<{
  id: string;
  x: number;
  y: number;
  zoom?: number;
  rotateX?: number;
  rotateY?: number;
  rotation?: number;
  /** Motion blur shutter in frames (0 off). */
  blur?: number;
  children: React.ReactNode;
}> = ({ id, x, y, zoom = 1, rotateX = 0, rotateY = 0, rotation = 0, blur = 0, children }) => (
  <Layer id={id} motionBlur={blur > 0 ? { samples: 8, shutter: blur } : undefined}>
    <Layer id={id + '-eye'} x={W / 2} y={H / 2} scale={zoom} rotateX={rotateX} rotateY={rotateY} rotation={rotation}>
      <Layer id={id + '-world'} x={-x} y={-y}>
        {children}
      </Layer>
    </Layer>
  </Layer>
);

/** A soft, bounded handheld drift: pixels of x and y, a function of the frame. Keep the amplitude under 1% of the
 *  frame. */
export const drift = (f: number, amp: number, seed = 0) => ({
  x: amp * (Math.sin(f * 0.021 + seed) * 0.6 + Math.sin(f * 0.053 + seed * 2.3) * 0.4),
  y: amp * (Math.sin(f * 0.017 + seed * 1.7) * 0.6 + Math.sin(f * 0.047 + seed) * 0.4),
});

// ---------------------------------------------------------------------------------------------------------------
// Curves

/** A monotone cubic (Fritsch-Carlson) through points with increasing x. Returns y at any x, with no overshoot. */
export function monotone(xs: number[], ys: number[]): (x: number) => number {
  const n = xs.length;
  if (n === 1) return () => ys[0];
  const dx = xs.slice(1).map((x, i) => x - xs[i]);
  const s = dx.map((d, i) => (ys[i + 1] - ys[i]) / d);
  const m = new Array(n).fill(0);
  m[0] = s[0];
  m[n - 1] = s[n - 2];
  for (let i = 1; i < n - 1; i++) m[i] = s[i - 1] * s[i] <= 0 ? 0 : (s[i - 1] + s[i]) / 2;
  for (let i = 0; i < n - 1; i++) {
    if (s[i] === 0) {
      m[i] = 0;
      m[i + 1] = 0;
    } else {
      const a = m[i] / s[i];
      const b = m[i + 1] / s[i];
      const h = Math.hypot(a, b);
      if (h > 3) {
        m[i] = (3 * a * s[i]) / h;
        m[i + 1] = (3 * b * s[i]) / h;
      }
    }
  }
  return (x: number) => {
    if (x <= xs[0]) return ys[0];
    if (x >= xs[n - 1]) return ys[n - 1];
    let i = 0;
    while (x > xs[i + 1]) i++;
    const h = dx[i];
    const t = (x - xs[i]) / h;
    const t2 = t * t;
    const t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * ys[i] + (t3 - 2 * t2 + t) * h * m[i] + (-2 * t3 + 3 * t2) * ys[i + 1] + (t3 - t2) * h * m[i + 1];
  };
}

/** Sample a curve y(x) from x0 to x1 into an SVG polyline (`M x y L ...`), a point about every `step` px. */
export function curvePath(y: (x: number) => number, x0: number, x1: number, step = 5): { d: string; pts: [number, number][] } {
  const n = Math.max(2, Math.ceil((x1 - x0) / step));
  const pts: [number, number][] = [];
  for (let i = 0; i <= n; i++) {
    const x = x0 + ((x1 - x0) * i) / n;
    pts.push([x, y(x)]);
  }
  const d = pts.map(([x, py], i) => `${i ? 'L' : 'M'}${x.toFixed(2)} ${py.toFixed(2)}`).join('');
  return { d, pts };
}

// ---------------------------------------------------------------------------------------------------------------
// Pieces

/** A tooltip card: label, a dot, the value, and an optional small line. Anchored by its bottom centre. */
export const Tooltip: React.FC<{
  id: string;
  x: number;
  y: number;
  label: string;
  value: string;
  note?: string;
  dot: string;
  theme: Theme;
  fonts: Fonts;
  opacity?: number;
  scale?: number;
  width?: number;
}> = ({ id, x, y, label, value, note, dot, theme, fonts, opacity = 1, scale = 1, width = 280 }) => {
  const h = note ? 136 : 112;
  return (
    <Layer id={id} x={x} y={y} anchorX={width / 2} anchorY={h} opacity={opacity} scale={scale}
      effects={[dropShadow({ y: 14, blur: 32, color: theme.shadow })]}>
      <Rect id={id + '-card'} width={width} height={h} radius={16} fill={theme.tip} stroke={{ color: theme.border, width: 1.5 }} />
      <Text id={id + '-label'} x={24} y={20} font={fonts.sans} weight={500} size={20} color={theme.muted}>{label}</Text>
      <Rect id={id + '-dot'} x={24} y={61} width={14} height={14} radius={7} fill={dot} />
      <Text id={id + '-value'} x={50} y={50} font={fonts.mono} weight={500} size={36} color={theme.tipInk}>{value}</Text>
      {note ? (
        <Text id={id + '-note'} x={24} y={98} font={fonts.sans} weight={500} size={19} color={dot}>{note}</Text>
      ) : null}
    </Layer>
  );
};

/** The card a chart sits on. */
export const Card: React.FC<{ id: string; x: number; y: number; width: number; height: number; theme: Theme; radius?: number }> = ({
  id, x, y, width, height, theme, radius = 36,
}) => (
  <Rect id={id} x={x} y={y} width={width} height={height} radius={radius} fill={theme.card} stroke={{ color: theme.border, width: 2 }}
    effects={[dropShadow({ y: 24, blur: 60, color: theme.shadow })]} />
);

/** Ground: a flat colour with a very slow light falloff, for the whole frame. */
export const Ground: React.FC<{ theme: Theme; dark: boolean }> = ({ theme, dark }) => (
  <Layer id="ground">
    <Rect id="ground-base" width={W} height={H} fill={theme.bg} />
    <Rect id="ground-light" width={W} height={H}
      fill={{ type: 'radial', units: 'box', cx: 0.5, cy: 0.35, r: 0.8,
        stops: [{ offset: 0, color: dark ? '#ffffff05' : '#ffffffcc' }, { offset: 1, color: '#ffffff00' }] }} />
  </Layer>
);

/** Small tag: a chip with a delta ("+12.4%") in the accent. Width follows the text (mono, 0.6 em per char). */
export const Chip: React.FC<{ id: string; x: number; y: number; text: string; color: string; fonts: Fonts; size?: number; opacity?: number }> = ({
  id, x, y, text, color, fonts, size = 24, opacity = 1,
}) => {
  const w = monoWidth(text, size) + size * 1.2;
  const h = size * 1.7;
  return (
    <Layer id={id} x={x} y={y} opacity={opacity}>
      <Rect id={id + '-bg'} width={w} height={h} radius={h / 2} fill={hexA(color, 0.14)} />
      <Text id={id + '-t'} x={size * 0.6} y={(h - size * 1.25) / 2} font={fonts.mono} weight={500} size={size} color={color}>{text}</Text>
    </Layer>
  );
};

// ---------------------------------------------------------------------------------------------------------------
// Scales

/** A "nice" axis for data between lo and hi: [min, max, step] with round ticks, about `count` of them. */
export function niceScale(lo: number, hi: number, count = 4): { min: number; max: number; step: number; ticks: number[] } {
  const span = Math.max(1e-9, hi - lo);
  const raw = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const norm = raw / mag;
  const step = (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10) * mag;
  const min = Math.floor(lo / step) * step;
  const max = Math.ceil(hi / step) * step;
  const ticks: number[] = [];
  for (let v = min; v <= max + step * 1e-6; v += step) ticks.push(v);
  return { min, max, step, ticks };
}

/** Wrap a draw-in so an effect that must keep to the plot is cut off at the plot edge. */
export const Hairline: React.FC<{ id: string; x0: number; x1: number; y: number; color: string; dash?: boolean; opacity?: number; width?: number }> = ({
  id, x0, x1, y, color, dash = true, opacity = 1, width = 2,
}) => (
  <Path_ id={id} d={`M${x0} ${y}H${x1}`} stroke={stroke(color, width, { cap: 'round', dash: dash ? [1, 10] : undefined })} opacity={opacity} />
);
